        .st-anchor-col.right {
            text-align: right;
            font-family: var(--font-serif);
            font-weight: 400;
            color: var(--txt-secondary);
        }

        /* --- 6. 下层书名号与纵向竖线箴言 --- */
        .st-book-title-block {
            font-size: clamp(28px, 4cqw, 36px);
            font-weight: normal; /* 毛垦故障宋体自带美学设计感，无需二次机械加粗 */
            color: var(--accent);
            text-align: center;
            letter-spacing: 2.5px;
            margin-top: 10px;
            font-family: var(--font-title);
            transition: var(--transition-base);
        }

        /* 竖线精致箴言排版 */
        .st-poetic-bar-container {
            width: 100%;
            display: flex;
            flex-direction: column; /* 纵向排布支撑多行单独居中对齐 */
            align-items: center;
            justify-content: center;
            gap: 10px; /* 纵向行间距 */
            font-size: clamp(16px, 2.4cqw, 19px);
            color: var(--txt-primary);
            line-height: 1.6;
            letter-spacing: 1.5px;
            text-align: center;
            transition: var(--transition-base);
            font-family: var(--font-poetic);
            font-weight: normal;
        }

        .st-poetic-line {
            display: block;
            width: 100%;
            text-align: center; /* 确保多行状态下每行单独物理居中 */
            word-break: break-all;
        }

        /* --- 7. 频谱底部对齐可视化波形分割线 --- */
        .st-visualizer-divider {
            width: 100%;
            height: 18px;
            display: flex;
            align-items: flex-end; /* 底部绝对固定对齐 */
            justify-content: center;
            gap: 3px; /* 间距微调，使30柱紧凑排布 */
            margin-top: 8px;
            border-bottom: 1px solid var(--border-line);
            padding-bottom: 0; /* 移除底部内边距，使波形底轴紧密贴合 */
            box-sizing: content-box;
        }

        .st-vis-bar {
            width: 3.5px; /* 加宽频谱柱，视觉效果更具实体质感 */
            height: 2px; /* 初始底部锚定高度 */
            background-color: var(--txt-muted);
            border-radius: 1.5px; /* 同步微调圆角，保持胶囊边缘温润感 */
            opacity: 0.45;
            transform-origin: bottom; /* 动画起点设定在底部 */
            transition: var(--transition-base);
        }

        /* 30个频谱柱的高低交错与平滑波动波形 */
        .st-vis-bar:nth-child(10n+1) { animation: st-bounce-up 1.0s ease-in-out infinite alternate; animation-delay: 0.1s; }
        .st-vis-bar:nth-child(10n+2) { animation: st-bounce-up 1.4s ease-in-out infinite alternate; animation-delay: 0.3s; }
        .st-vis-bar:nth-child(10n+3) { animation: st-bounce-up 0.8s ease-in-out infinite alternate; animation-delay: 0.0s; }
        .st-vis-bar:nth-child(10n+4) { animation: st-bounce-up 1.2s ease-in-out infinite alternate; animation-delay: 0.5s; }
        .st-vis-bar:nth-child(10n+5) { animation: st-bounce-up 0.9s ease-in-out infinite alternate; animation-delay: 0.2s; }
        .st-vis-bar:nth-child(10n+6) { animation: st-bounce-up 1.5s ease-in-out infinite alternate; animation-delay: 0.4s; }
        .st-vis-bar:nth-child(10n+7) { animation: st-bounce-up 1.1s ease-in-out infinite alternate; animation-delay: 0.15s; }
        .st-vis-bar:nth-child(10n+8) { animation: st-bounce-up 1.3s ease-in-out infinite alternate; animation-delay: 0.6s; }
        .st-vis-bar:nth-child(10n+9) { animation: st-bounce-up 0.7s ease-in-out infinite alternate; animation-delay: 0.35s; }
        .st-vis-bar:nth-child(10n+10) { animation: st-bounce-up 1.2s ease-in-out infinite alternate; animation-delay: 0.25s; }

        @keyframes st-bounce-up {
            0% { height: 2px; }
            100% { height: 16px; } /* 顶部向上生发高度 */
        }

        /* --- 8. 页脚与极简控制器 --- */
        .st-editorial-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 4px;
            padding-top: 4px;
        }

        /* 极简控制器 */
        .st-astrolabe-control {
            display: flex;
            align-items: center;
            gap: 6px;
            cursor: pointer;
            padding: 4px 10px;
            border-radius: 12px;
            background: var(--axis-line);
            border: 1px solid var(--border-line);
            font-family: var(--font-sans);
            font-size: 10px;
            font-weight: 700;
            letter-spacing: 1px;
            color: var(--txt-secondary);
            transition: var(--transition-base);
        }

        .st-astrolabe-control:hover {
            color: var(--accent);
            border-color: var(--accent);
            transform: translateY(-1px);
        }

        .st-chronos-clock {
            font-size: clamp(11px, 2cqw, 13px);
            font-weight: 600; /* 字体加粗处理，强化读数清晰度 */
            color: var(--txt-muted);
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* --- 9. 单色同谱深浅呼吸 --- */
        @keyframes accent-glow-day {
            0%, 100% { color: rgba(179, 44, 44, 1); }
            50% { color: rgba(179, 44, 44, 0.45); }
        }

        @keyframes accent-glow-night {
            0%, 100% { color: rgba(46, 134, 222, 1); }
            50% { color: rgba(46, 134, 222, 0.45); }
        }

        /* --- 10. 移动端自适应布局形态切换 --- */
        @container (max-width: 480px) {
            .st-hero-grid {
                grid-template-columns: 1fr;
                gap: 24px;
                justify-items: center;
