        <canvas id="st-particle-canvas" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0;"></canvas>

        <!-- 1. Hero Block: 非对称网格、唱针黑胶与手写体 -->
