                <!-- 小号编号移入手写体下方 -->
                <div class="st-quote-watermark" id="st-render-watermark">NO.01</div>
                <!-- 纯白描文学摘抄 -->
                <div class="st-hero-quote" id="st-render-quote">
                    时间正在碎裂的镜中沉睡。
                    <span class="st-hero-author" id="st-render-author">— 佚名</span>
