                        <circle cx="24" cy="8" r="2" fill="#222"/>
                        <!-- 针臂 -->
                        <path d="M24 14 L24 38 L14 52" stroke="#aaa" stroke-width="2" stroke-linecap="round"/>
                        <!-- 针头与抬针手柄 -->
                        <rect x="10" y="50" width="8" height="5" rx="1.5" fill="#333" transform="rotate(-15 14 52)"/>
                        <path d="M10 52 L6 50" stroke="#888" stroke-width="1"/>
