<script>
document.addEventListener('DOMContentLoaded', function() {
    const rawDataElement = document.getElementById('raw-data');
    const bcBoardEl = document.getElementById('bc-board');
    const postListEl = document.getElementById('post-list');
    const adContentEl = document.getElementById('ad-content');
    const statusInfoEl = document.getElementById('status-info');

    // --- 弹窗广告轮播 ---
    // 1. 设置一个默认的兜底广告（在网络慢、或者远程还没拉取到的时候显示）
    let ads = ['<i class="fas fa-spinner fa-spin"></i> 正在连接广告联盟服务器...'];
    let adIndex = 0;
    adContentEl.innerHTML = ads[0]; 

    // 2. 随机轮播逻辑
    setInterval(() => {
        if (ads.length > 1) {
            let newIndex;
            // 抽出一个新数字，如果和上一次一样，就重新抽，避免连续播放同一条
            do {
                newIndex = Math.floor(Math.random() * ads.length);
            } while (newIndex === adIndex);

            adIndex = newIndex;
            adContentEl.innerHTML = ads[adIndex];
        } else if (ads.length === 1) {
            adContentEl.innerHTML = ads[0];
        }
    }, 4000);

    // 3. 异步请求远程 JSON 库
    const timestamp = Date.now();
    const remoteAdUrl = `https://cdn.jsdelivr.net/gh/colerith/tsukuyomi@main/ads_v4.json?t=${timestamp}`;

    fetch(remoteAdUrl)
        .then(response => {
            if (!response.ok) throw new Error('网络请求失败');
            return response.json();
        })
        .then(data => {
            if (Array.isArray(data) && data.length > 0) {
                ads = data; // 用远程拉取的数据替换掉本地的兜底数组
                adIndex = 0; 
                adContentEl.innerHTML = ads[0]; // 立刻显示第一条新广告
            }
        })
        .catch(error => {
            console.error('【广告联盟拦截】：牛皮癣服务器连接失败', error);
            // 如果拉取失败，就悄悄换成单机版兜底文案
            ads = ['【网络异常】无法连接到远程服务器，请检查您的拨号连接！'];
            adContentEl.innerHTML = ads[0];
        });

    const deepClean = (str) => {
        if (!str) return '';
        return str.replace(/ /ig, ' ')
                  .replace(/^[\s\u3000\xA0\u200B\u200C\u200D\uFEFF]+/, '')
                  .replace(/[\s\u3000\xA0\u200B\u200C\u200D\uFEFF]+$/, '');
    };

    // 去掉评论正文最外层多余的半角/全角方括号，保留正文内部的括号
    const stripCommentBrackets = (str) => {
        const text = deepClean(str);
        const hasOuterBrackets = (text.startsWith('[') && text.endsWith(']'))
            || (text.startsWith('［') && text.endsWith('］'));
        return hasOuterBrackets ? deepClean(text.slice(1, -1)) : text;
    };

    const rawText = rawDataElement.textContent || rawDataElement.innerText; 
    const lines = rawText.split('\n');

    // 新增 tags 字段
    let parsedData = { board: '', title: '', tags: '', opId: '', opContentLines: [], replies: [], stats: '' };
    let inReplies = false;
    let inOPContent = false;
    let currentReply = null;

    lines.forEach(originalLine => {
        const line = deepClean(originalLine);
        if (!line) return; 

        if (line.includes('论坛板块：')) {
            parsedData.board = deepClean(line.replace(/.*论坛板块：/, ''));
        } else if (line.includes('帖子标题：')) {
            parsedData.title = deepClean(line.replace(/.*帖子标题：/, ''));
        } else if (line.includes('帖子标签：')) { // 捕获标签
            parsedData.tags = deepClean(line.replace(/.*帖子标签：/, ''));
        } else if (line.includes('楼主ID：')) {
            parsedData.opId = deepClean(line.replace(/.*楼主ID：/, ''));
        } else if (line.includes('帖子正文：')) {
            inOPContent = true;
            const content = deepClean(line.replace(/.*帖子正文：/, ''));
            if (content) parsedData.opContentLines.push(content);
        } else if (line.includes('<帖子回复>')) {
            inOPContent = false;
            inReplies = true;
        } else if (line.includes('</帖子回复>')) {
            inReplies = false;
            if (currentReply) {
                currentReply.content = currentReply.contentLines.join('\n');
                parsedData.replies.push(currentReply);
                currentReply = null;
            }
        } else if (line.includes('帖子数据：')) {
            parsedData.stats = deepClean(line.replace(/.*帖子数据：/, ''));
        } else if (inOPContent) {
            const cleanLine = originalLine.trim();
            if (cleanLine) {
                parsedData.opContentLines.push(cleanLine);
            }
        } else if (inReplies) {
            const match = originalLine.trim().match(/^[\s\u3000\xA0]*@(.+?)[：:](.*)/);
            if (match) {
                if (currentReply) {
                    currentReply.content = currentReply.contentLines.join('\n');
                    parsedData.replies.push(currentReply);
                }
                currentReply = {
                    user: deepClean(match[1]),
                    contentLines: []
                };
                const content = deepClean(match[2]);
                if (content) currentReply.contentLines.push(content);
            } else if (currentReply) {
                const cleanLine = originalLine.trim();
                if (cleanLine) {
                    currentReply.contentLines.push(cleanLine);
                }
            }
        }
    });

    if (currentReply) {
        currentReply.content = currentReply.contentLines.join('\n');
        parsedData.replies.push(currentReply);
        currentReply = null;
    }

    parsedData.opContent = parsedData.opContentLines.join('\n');

    // 【修改点】：动态取值，将保底词改成“默认版块”
    bcBoardEl.textContent = parsedData.board || "默认版块";

    // 动态生成底部状态数据
    const onlineUsers = Math.floor(Math.random() * 60) + 5;
    const todayVisits = Math.floor(Math.random() * 800) + 120;
    statusInfoEl.innerHTML = `在线用户: ${onlineUsers} | 今日访问: ${todayVisits}`;

    // --- 提取 Emoji 和 纯昵称 的解析工具 ---
    function extractUserInfo(rawName) {
        if (!rawName) return { emoji: '', name: '未知用户' };
        // 使用 ES2018 的 Unicode 属性正则，精准匹配开头的 Emoji
        const regex = /^(\p{Emoji_Presentation}|\p{Extended_Pictographic})\s*(.*)/u;
        const match = rawName.match(regex);
        if (match) {
            return { emoji: match[1], name: match[2].trim() || '无名氏' };
        } else {
            // 如果楼主或回复者没带 Emoji，则只返回名字
            return { emoji: '', name: rawName.trim() }; 
        }
    }

    function getRandomColor() { return `hsl(${Math.floor(Math.random() * 360)}, 50%, 60%)`; }
    function getRandomIP() { return `114.104.${Math.floor(Math.random() * 255)}.***`; }
    function getRandomUserID() { return `${Math.floor(Math.random()*9+1)}${Date.now()}`.substring(0, 10); }

    let baseTime = new Date();
    baseTime.setHours(10, 21, 22);
    function getTimeString() {
        const timeStr = baseTime.toTimeString().split(' ')[0];
        baseTime.setMinutes(baseTime.getMinutes() + Math.floor(Math.random() * 5) + 1);
        return timeStr;
    }

    function renderOP() {
        if (!parsedData.opContent) return;
        const time = getTimeString();
        const opDiv = document.createElement('div');
        opDiv.className = 'op-card';
        const replyCount = parsedData.replies.length;

        const opInfo = extractUserInfo(parsedData.opId);
        const avatarColor = getRandomColor(); 

        const tagsHTML = parsedData.tags ? `<div style="font-size: 12px; color: #0000ee; margin-top: 8px;"><b>标签：</b>${parsedData.tags}</div>` : '';

        opDiv.innerHTML = `
            <div class="op-header">
                <div style="display: flex; align-items: center;">
                    <span class="op-title">${parsedData.title || "未知标题"}</span>
                    <i class="fas fa-fire op-hot-icon"></i>
                </div>
                <div class="op-meta">楼主: ${opInfo.name} | 发布于: ${time}</div>
            </div>

            <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 10px; background: #fff; padding: 5px; border: 1px inset #ccc; width: fit-content;">
                <div class="avatar" style="background-color: ${avatarColor};">${opInfo.emoji}</div>
                <span style="font-size: 12px; color: #555; font-weight: bold;">${opInfo.name}</span>
            </div>

            <div class="op-body">${parsedData.opContent}${tagsHTML}<br><br><span class="fake-link-blue">..... 展开</span></div>
            <div class="op-recessed-bar">共 ${replyCount} 条评论，看来热聊</div>
        `;
        postListEl.appendChild(opDiv);
    }

    function renderReply(user, content, replyToUser, time) {
        const avatarColor = getRandomColor();
        const ip = getRandomIP();
        const userID = getRandomUserID();
        const userInfo = extractUserInfo(user);
        const replyToInfo = extractUserInfo(replyToUser);
        const cardDiv = document.createElement('div');
        cardDiv.className = 'card';

        cardDiv.innerHTML = `
            <div class="card-header">
                <div class="card-user-info">
                    <div class="avatar" style="background-color: ${avatarColor};">${userInfo.emoji}</div>
                    <div class="user-meta">
                        <span class="username">${userInfo.name}</span>
                        <span class="user-id">ID: ${userID}</span>
                    </div>
                </div>
                <div class="card-time-wrap">
                    <span>${time}</span>
                    <button class="reply-btn-3d"><i class="fas fa-reply"></i> 回复</button>
                </div>
            </div>
            <div class="card-body">
                <div class="reply-quote">回复 ${replyToInfo.name}:</div>
                <div class="reply-text">${content}</div>
            </div>
            <div class="card-footer">
                <div class="stat-item"><i class="fas fa-thumbs-up stat-icon"></i> 赞(${Math.floor(Math.random() * 80) + 1})</div>
                <span>IP: ${ip}</span>
            </div>
        `;
        postListEl.appendChild(cardDiv);
    }

    renderOP();
    parsedData.replies.forEach(reply => {
        const replyTo = parsedData.opId; 
        renderReply(reply.user, stripCommentBrackets(reply.content), replyTo, getTimeString());
    });
});
</script>

</body>
</html>



