        .tab-btn:hover { color: var(--accent); background: var(--bg-card); opacity: 1; border-color: var(--border-color); }
        .tab-btn.active {
            color: var(--accent); font-weight: 600; opacity: 1;
            background: var(--bg-card);
            box-shadow: 0 4px 10px rgba(0,0,0,0.05);
            border-color: var(--border-color);
